int divide_integers(int dividend,int divisor){unsigned int a;unsigned int b;unsigned int quotient;unsigned int chunk;unsigned int multiple;int negative;if(divisor==0)return 2147483647;if(dividend==(-2147483647-1)&&divisor==-1)return 2147483647;negative=(dividend<0)!=(divisor<0);if(dividend<0)a=0U-(unsigned int)dividend;else a=(unsigned int)dividend;if(divisor<0)b=0U-(unsigned int)divisor;else b=(unsigned int)divisor;quotient=0U;while(a>=b){chunk=b;multiple=1U;while(chunk<=a-chunk&&chunk<0x80000000U){chunk=chunk<<1;multiple=multiple<<1;}a=a-chunk;quotient=quotient+multiple;}if(negative)return (int)(0U-quotient);return (int)quotient;}
int main(void){if(divide_integers(10,3)!=3)return 1;if(divide_integers(7,-3)!=-2)return 2;if(divide_integers(-2147483647-1,-1)!=2147483647)return 3;if(divide_integers(-2147483647-1,1)!=-2147483647-1)return 4;if(divide_integers(-15,-4)!=3)return 5;return 42;}
